CREATE TABLE ad_clicks (
  ad_id BIGINT,
  click_time TIMESTAMP(3),
  WATERMARK FOR click_time AS click_time - INTERVAL '5' SECOND
) WITH ('connector' = 'kafka', 'topic' = 'ad-clicks' /* plus broker and format settings */);

SELECT ad_id, window_start, COUNT(*) AS clicks
FROM TABLE(TUMBLE(TABLE ad_clicks, DESCRIPTOR(click_time), INTERVAL '1' MINUTE))
GROUP BY ad_id, window_start, window_end;
